#!/usr/bin/env node
/**
 * check-external-links.cjs — report-only audit of external (cross-origin)
 * links in the built site. Intentional NON-BLOCKING: dead external links are
 * reported as warnings, not failures (a flaky 3rd-party host must not break
 * the deploy).
 *
 * Design:
 *  - Skips social "share-intent" hosts (twitter/linkedin/bsky/reddit/t.me/
 *    facebook/telegram/mastodon share URLs) — those are generated by the
 *    theme and are not content links.
 *  - Checks each distinct content URL with a HEAD (fallback GET), 8s timeout,
 *    concurrency cap 12. Treats 2xx/3xx as OK, 4xx/5xx/connection-refused as
 *    DEAD, and timeouts as WARNING (soft — could be transient).
 *  - Writes a machine-readable report to .ci/external-links-report.json.
 *
 * Usage: node scripts/check-external-links.cjs [publicDir]
 */
const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

const PUBLIC = process.argv[2] || path.join(__dirname, '..', 'public');
const SKIP_HOSTS = new Set([
  'twitter.com', 'www.twitter.com', 'x.com', 'www.linkedin.com', 'bsky.app',
  'reddit.com', 'www.reddit.com', 't.me', 'www.facebook.com', 'facebook.com',
  'telegram.me', 'mastodon.social', 't.co', 'tinyurl.com', 'bit.ly',
  'news.ycombinator.com', // HN submit links are share-intent
]);

function walk(dir, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) walk(full, out);
    else if (e.name.endsWith('.html')) out.push(full);
  }
}
const extRe = /href=["'](https?:\/\/[^"']+)["']/g;
const files = [];
walk(PUBLIC, files);
const seen = new Set();
for (const f of files) {
  const html = fs.readFileSync(f, 'utf8');
  let m;
  while ((m = extRe.exec(html))) seen.add(m[1]);
}
function hostOf(u) {
  try { return new URL(u.replace(/&amp;/g, '&')).host.toLowerCase(); }
  catch { return null; }
}

const candidates = [...seen].filter((u) => {
  const h = hostOf(u);
  return h && !SKIP_HOSTS.has(h);
});

function check(u) {
  return new Promise((resolve) => {
    const target = u.replace(/&amp;/g, '&'); // Hugo HTML-escapes & -> &amp; in hrefs
    let mod;
    try { mod = target.startsWith('https') ? https : http; } catch { return resolve({ u, status: 'error' }); }
    const req = mod.request(target, { method: 'HEAD', timeout: 8000, headers: { 'User-Agent': 'Mozilla/5.0 link-checker' } }, (res) => {
      const code = res.statusCode;
      res.resume();
      if (code >= 200 && code < 400) resolve({ u, status: 'ok', code });
      else if (code >= 300 && code < 400 && res.headers.location) resolve({ u, status: 'ok', code });
      else if (code === 405) resolve({ u, status: 'ok', code: 405 }); // HEAD not allowed; treat as ok
      else resolve({ u, status: 'dead', code });
    });
    req.on('timeout', () => { req.destroy(); resolve({ u, status: 'timeout' }); });
    req.on('error', (e) => resolve({ u, status: 'dead', err: e.code || e.message }));
    req.end();
  });
}

const CAP = 12;
async function run() {
  const results = [];
  for (let i = 0; i < candidates.length; i += CAP) {
    const batch = candidates.slice(i, i + CAP);
    const r = await Promise.all(batch.map(check));
    results.push(...r);
  }
  const dead = results.filter((r) => r.status === 'dead');
  const timeout = results.filter((r) => r.status === 'timeout');
  const report = { total: candidates.length, ok: results.length - dead.length - timeout.length, dead, timeout };
  fs.mkdirSync(path.join(__dirname, '..', '.ci'), { recursive: true });
  fs.writeFileSync(path.join(__dirname, '..', '.ci', 'external-links-report.json'), JSON.stringify(report, null, 2));
  console.log(`🔗 External links: ${candidates.length} checked, ${report.ok} ok, ${dead.length} DEAD, ${timeout.length} timeout(warn).`);
  for (const d of dead) console.log(`  ⚠ DEAD ${d.code || d.err}  ${d.u}`);
  for (const t of timeout.slice(0, 20)) console.log(`  ⏱ TIMEOUT ${t.u}`);
  process.exit(0); // report-only — never fail the build
}
if (!fs.existsSync(PUBLIC)) { console.error('public/ missing — run hugo build first'); process.exit(0); }
run();
